css:
.boardconvo-sim-container {
    padding: 28px;
    background: #f4f5f7;
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #1a2744;
}

.boardconvo-sim-header {
    background: linear-gradient(135deg, #0f1d3a 0%, #1a2744 100%);
    color: #ffffff;
    padding: 32px 36px;
    border-radius: 4px;
    border-left: 4px solid #c9a44b;
    margin-bottom: 24px;
    box-shadow: 0 2px 12px rgba(15,29,58,0.12);
}
.boardconvo-sim-header-meta {
    color: #c9a44b;
    font-size: 0.72rem;
    letter-spacing: 0.18em;
    text-transform: uppercase;
    margin-bottom: 10px;
    font-weight: 600;
}
.boardconvo-sim-header h1 {
    margin: 0 0 8px 0;
    font-size: 1.55rem;
    font-weight: 600;
    letter-spacing: -0.01em;
}
.boardconvo-sim-subtitle {
    color: #c8d0e0;
    font-size: 0.95rem;
    line-height: 1.5;
    max-width: 720px;
}

.boardconvo-sim-period-strip {
    display: flex;
    gap: 12px;
    margin-bottom: 20px;
    flex-wrap: wrap;
}
.boardconvo-sim-period-pill {
    background: #ffffff;
    border: 1px solid #d6dae2;
    padding: 10px 18px;
    border-radius: 4px;
    font-size: 0.85rem;
    color: #1a2744;
    font-weight: 500;
}
.boardconvo-sim-period-pill strong {
    color: #81692e;
    font-weight: 700;
    margin-left: 6px;
}
.boardconvo-sim-period-countdown {
    background: #1a2744;
    color: #ffffff;
    border-color: #1a2744;
}

.boardconvo-sim-status-cards {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
    gap: 14px;
    margin-bottom: 24px;
}
.boardconvo-sim-status-card {
    background: #ffffff;
    border: 1px solid #d6dae2;
    border-top: 3px solid #1a2744;
    border-radius: 4px;
    padding: 20px 22px;
    transition: transform 0.2s ease, box-shadow 0.2s ease;
}
.boardconvo-sim-status-card:hover {
    transform: translateY(-2px);
    box-shadow: 0 6px 18px rgba(15,29,58,0.10);
}
.boardconvo-sim-card-trust { border-top-color: #1a4f8a; }
.boardconvo-sim-card-prep { border-top-color: #c9a44b; }
.boardconvo-sim-card-value { border-top-color: #2d6a4f; }
.boardconvo-sim-card-asks { border-top-color: #8b1e3f; }

.boardconvo-sim-label {
    color: #666d7a;
    font-size: 0.72rem;
    letter-spacing: 0.10em;
    text-transform: uppercase;
    margin-bottom: 10px;
    font-weight: 600;
}
.boardconvo-sim-value {
    font-size: 2.1rem;
    font-weight: 700;
    color: #1a2744;
    line-height: 1;
    margin-bottom: 8px;
}
.boardconvo-sim-sub {
    color: #666d7a;
    font-size: 0.78rem;
}

.boardconvo-sim-briefing {
    background: #ffffff;
    border: 1px solid #d6dae2;
    border-left: 3px solid #c9a44b;
    border-radius: 4px;
    padding: 24px 28px;
    margin-bottom: 20px;
}
.boardconvo-sim-briefing-eyebrow {
    color: #81692e;
    font-size: 0.7rem;
    letter-spacing: 0.16em;
    text-transform: uppercase;
    margin-bottom: 8px;
    font-weight: 700;
}
.boardconvo-sim-briefing h2 {
    margin: 0 0 12px 0;
    font-size: 1.25rem;
    color: #1a2744;
    font-weight: 600;
}
.boardconvo-sim-briefing-body {
    color: #2c3e50;
    font-size: 0.95rem;
    line-height: 1.6;
}

.boardconvo-sim-controls {
    background: #ffffff;
    border: 1px solid #d6dae2;
    border-radius: 4px;
    padding: 24px 28px;
    margin-bottom: 20px;
}
.boardconvo-sim-controls h3 {
    color: #1a2744;
    font-size: 0.85rem;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    margin: 0 0 18px 0;
    padding-bottom: 12px;
    border-bottom: 1px solid #e5e7eb;
}
.boardconvo-sim-field {
    margin-bottom: 16px;
}
.boardconvo-sim-field label {
    display: block;
    font-size: 0.85rem;
    font-weight: 600;
    color: #1a2744;
    margin-bottom: 6px;
}
.boardconvo-sim-field-note {
    background: #fdf6e3;
    border-left: 3px solid #c9a44b;
    padding: 12px 14px;
    color: #5a4a1f;
    font-size: 0.88rem;
    margin-bottom: 16px;
    border-radius: 0 4px 4px 0;
}
.boardconvo-sim-controls input[type="number"],
.boardconvo-sim-controls input[type="text"],
.boardconvo-sim-controls select {
    background: #ffffff;
    border: 1px solid #c8cfd8;
    color: #1a2744;
    border-radius: 4px;
    padding: 9px 12px;
    width: 100%;
    font-size: 0.92rem;
    font-family: inherit;
}
.boardconvo-sim-controls select option {
    background: #ffffff;
    color: #1a2744;
}
.boardconvo-sim-controls input:focus,
.boardconvo-sim-controls select:focus {
    outline: none;
    border-color: #c9a44b;
    box-shadow: 0 0 0 2px rgba(201,164,75,0.18);
}
.boardconvo-sim-hint-text {
    color: #666d7a;
    font-size: 0.78rem;
    margin-top: 4px;
    font-style: italic;
}
.boardconvo-sim-checklist {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
    gap: 8px;
    margin-bottom: 16px;
}
.boardconvo-sim-check {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 10px 14px;
    background: #f8f9fa;
    border: 1px solid #e5e7eb;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.9rem;
    color: #1a2744;
    transition: background 0.2s ease, border-color 0.2s ease;
}
.boardconvo-sim-check:hover {
    background: #fdf6e3;
    border-color: #c9a44b;
}
.boardconvo-sim-check input[type="checkbox"] {
    width: 16px;
    height: 16px;
    accent-color: #1a2744;
}
.boardconvo-sim-button-row {
    display: flex;
    gap: 12px;
    margin-top: 18px;
    padding-top: 16px;
    border-top: 1px solid #e5e7eb;
    flex-wrap: wrap;
}
.boardconvo-sim-button-row .btn-primary {
    background: #1a2744;
    border-color: #1a2744;
    color: #ffffff;
    padding: 10px 24px;
    font-weight: 600;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    font-size: 0.82rem;
    border-radius: 4px;
}
.boardconvo-sim-button-row .btn-primary:hover {
    background: #c9a44b;
    border-color: #c9a44b;
}

.boardconvo-sim-coach {
    background: #1a2744;
    color: #ffffff;
    padding: 22px 28px;
    border-radius: 4px;
    border-left: 4px solid #c9a44b;
    margin-bottom: 20px;
    box-shadow: 0 2px 12px rgba(15,29,58,0.12);
}
.boardconvo-sim-coach-eyebrow {
    color: #c9a44b;
    font-size: 0.7rem;
    letter-spacing: 0.16em;
    text-transform: uppercase;
    margin-bottom: 10px;
    font-weight: 700;
}
.boardconvo-sim-coach #coachFeedback {
    font-size: 0.98rem;
    line-height: 1.55;
    color: #e8ecf3;
}

.boardconvo-sim-history {
    background: #ffffff;
    border: 1px solid #d6dae2;
    border-radius: 4px;
    padding: 22px 28px;
    margin-bottom: 20px;
}
.boardconvo-sim-history h3 {
    color: #1a2744;
    font-size: 0.85rem;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    margin: 0 0 14px 0;
}
.boardconvo-sim-history table {
    margin: 0;
    font-size: 0.9rem;
}
.boardconvo-sim-history th {
    background: #1a2744;
    color: #ffffff;
    font-weight: 600;
    font-size: 0.78rem;
    letter-spacing: 0.05em;
    text-transform: uppercase;
    padding: 10px 12px;
    border: none;
}
.boardconvo-sim-history td {
    padding: 10px 12px;
    border-bottom: 1px solid #eef0f3;
    color: #2c3e50;
}

.boardconvo-sim-chart {
    background: #ffffff;
    border: 1px solid #d6dae2;
    border-radius: 4px;
    padding: 22px 28px;
    height: 380px;
}
.boardconvo-sim-chart h3 {
    color: #1a2744;
    font-size: 0.85rem;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    margin: 0 0 14px 0;
}
.boardconvo-sim-chart canvas {
    max-height: 300px;
}

@media (max-width: 768px) {
    .boardconvo-sim-container { padding: 16px; }
    .boardconvo-sim-header { padding: 22px; }
    .boardconvo-sim-header h1 { font-size: 1.2rem; }
    .boardconvo-sim-status-cards { grid-template-columns: 1fr 1fr; }
    .boardconvo-sim-value { font-size: 1.6rem; }
    .boardconvo-sim-checklist { grid-template-columns: 1fr; }
}


/* --- v1.1.0: focus visibility, reduced motion, completion panel --- */
.boardconvo-sim-container :focus-visible,
.boardconvo-sim-container select:focus-visible,
.boardconvo-sim-container input:focus-visible,
.boardconvo-sim-container .btn:focus-visible {
    outline: 3px solid #0f1d3a;
    outline-offset: 2px;
}

@media (prefers-reduced-motion: reduce) {
    .boardconvo-sim-container *,
    .boardconvo-sim-container *::before,
    .boardconvo-sim-container *::after {
        animation-duration: 0.001ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.001ms !important;
        scroll-behavior: auto !important;
    }
}

.boardconvo-sim-completion {
    background: #ffffff;
    border: 2px solid #0f1d3a;
    border-left: 6px solid #81692e;
    border-radius: 6px;
    padding: 26px 30px;
    margin: 20px 0;
}
.bc-debrief-tag {
    display: inline-block;
    font-size: 0.7rem; letter-spacing: 0.16em; text-transform: uppercase; font-weight: 700;
    color: #ffffff; background: #0f1d3a; padding: 4px 10px; border-radius: 3px; margin-bottom: 14px;
}
.bc-debrief-score { line-height: 1; }
.bc-debrief-num { font-size: 46px; font-weight: 700; color: #0f1d3a; }
.bc-debrief-den { font-size: 18px; color: #666d7a; }
.bc-debrief-band { font-size: 15px; font-weight: 600; color: #81692e; margin: 6px 0 4px; }
.bc-debrief-kpis { font-size: 0.82rem; color: #666d7a; margin-bottom: 16px; line-height: 1.6; }
.bc-debrief-list { margin: 0 0 16px 0; padding-left: 20px; }
.bc-debrief-list li { margin-bottom: 8px; color: #333a45; line-height: 1.55; }
.bc-debrief-close {
    margin: 0; padding-top: 14px; border-top: 1px solid #e5e7eb;
    font-style: italic; color: #333a45; line-height: 1.55;
}

