            if (!history.length) return {};
            const lastTrust = history[history.length - 1].results
                ? (history[history.length - 1].results.boardTrust || 0)
                : 0;
            const totalValue = history.reduce((s, r) => s + ((r.results && r.results.valueDelta) || 0), 0);
            const totalPrep = history.reduce((s, r) => s + ((r.results && r.results.prepDelta) || 0), 0);

            const t = window.mySimulation.t.bind(window.mySimulation);
            let outcome = 'theatre';
            let insights = [];
            if (totalValue >= 110 && lastTrust >= 70) {
                outcome = 'clean_decision';
            } else if (totalValue >= 70) {
                outcome = 'working_session';
            } else if (totalValue >= 30) {
                outcome = 'mixed';
            } else {
                outcome = 'theatre';
            }
            insights.push(t('insight_' + outcome));

            if (lastTrust < 50) insights.push(t('insight_trust_hit'));
            if (totalPrep < 50) insights.push(t('insight_prep_low'));
            const composite = this._composite(history);

            return {
                composite: composite,
                overallScore: composite,
                totalScore: composite,
                score: composite,
                totalValue: Math.round(totalValue),
                preparation: Math.round(totalPrep),
                boardTrust: Math.round(lastTrust),
                outcome: outcome,
                performance: outcome,
                performanceKey: outcome,
                performanceLabel: t('outcome_' + outcome),
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            if (state.domainState.boardTrust < 40) return window.mySimulation.t('hint_low_trust');
            if (state.currentPeriod >= 2 && state.domainState.preparation < 30) return window.mySimulation.t('hint_low_prep');
            if (results.valueDelta && results.valueDelta < 0) return window.mySimulation.t('hint_negative_value');
            return null;
        }

