                { key: 'results.prepDelta', label: 'Prep (+)', i18nKey: 'col_prep', formatter: (v) => (v >= 0 ? '+' : '') + Math.round(v) },
                { key: 'results.coach', label: 'Coach Note', i18nKey: 'col_coach' }
            ];
        }

        getPresets() { return null; }

        _updateBriefing(state) {
            const t = window.mySimulation.t.bind(window.mySimulation);
            const raw = Math.max(state.currentPeriod || 1, 1);
            const finished = raw > this.ROUNDS.length;
            this._finished = finished;
            const titleEl = document.getElementById('roundTitle');
            const descEl = document.getElementById('roundDescription');
            const controls = document.getElementById('controlsPanel');
            const donePanel = document.getElementById('completionPanel');

            if (finished) {
                for (let i = 1; i <= this.ROUNDS.length; i++) {
                    const p = document.getElementById('roundPanel' + i);
                    if (p) p.style.display = 'none';
                }
                if (titleEl) titleEl.innerHTML = t('debrief_title');
                if (descEl) descEl.innerHTML = t('debrief_briefing');
                if (controls) controls.style.display = 'none';
                this._renderCompletion();
                return;
            }
            if (controls) controls.style.display = '';
            if (donePanel) { donePanel.style.display = 'none'; donePanel.innerHTML = ''; }

            const period = raw;
            for (let i = 1; i <= this.ROUNDS.length; i++) {
                const panel = document.getElementById('roundPanel' + i);
                if (panel) panel.style.display = (i === period) ? 'block' : 'none';
            }
            if (titleEl) titleEl.innerHTML = t('r' + period + '_title');
            if (descEl) descEl.innerHTML = t('r' + period + '_desc');

            const submitBtn = document.getElementById('nextPeriodBtn');
            if (submitBtn) {
                submitBtn.textContent = t(period === this.ROUNDS.length ? 'submit_btn_final' : 'submit_btn');
            }
            this._syncControlsFromDecisions(state);
        }

        _syncControlsFromDecisions(state) {
            const hist = (state && state.history) || (window.mySimulation && window.mySimulation.state && window.mySimulation.state.history);
            if (!hist || !hist.length) return;
            const dec = (state && state.decisions) || (window.mySimulation && window.mySimulation.state && window.mySimulation.state.decisions) || {};
            const setVal = (id, v) => { const el = document.getElementById(id); if (el && v !== undefined && v !== null) el.value = v; };
            const setChk = (id, v) => { const el = document.getElementById(id); if (el && v !== undefined) el.checked = !!v; };
            setVal('askCountInput', dec.askCount);
            setVal('askTypeSelect', dec.askType);
            setVal('specificitySelect', dec.specificity);
            setChk('discloseBurn', dec.discloseBurn);
            setChk('discloseForecast', dec.discloseForecast);
            setChk('discloseChurn', dec.discloseChurn);
            setChk('discloseKeyPerson', dec.discloseKeyPerson);
            setChk('discloseFriction', dec.discloseFriction);
            setVal('planAttachedSelect', dec.planAttached);
            setVal('directorsInput', dec.directorsPreWired);
            setVal('daysBeforeInput', dec.daysBefore);
            setVal('preWireScriptSelect', dec.preWireScript);
            setVal('slideCountInput', dec.slideCount);
            setVal('askMomentSelect', dec.askMoment);
            setVal('deflectionSelect', dec.deflection);
        }

        _composite(history) {
            if (!history || !history.length) return 0;
            const lastTrust = (history[history.length - 1].results && history[history.length - 1].results.boardTrust) || 0;
            const totalValue = history.reduce((s, r) => s + ((r.results && r.results.valueDelta) || 0), 0);
            const valuePct = Math.max(0, Math.min(100, (totalValue / 150) * 100));
            return Math.round(0.6 * valuePct + 0.4 * lastTrust);
        }

        _renderCompletion() {
            const box = document.getElementById('completionPanel');
            if (!box) return;
            const sim = window.mySimulation;
            let summ = (sim && sim.lastSummary) || null;
            if (!summ && sim && sim.state && sim.state.history) summ = this.getPerformanceSummary(sim.state.history);
            if (!summ || !summ.insights) return;
            box.innerHTML = this.formatCompletionMessage(summ);
            box.style.display = 'block';
        }

        formatCompletionMessage(summary) {
            const t = window.mySimulation.t.bind(window.mySimulation);
            const s = summary || {};
            const score = (s.overallScore != null) ? s.overallScore : 0;
            const label = s.performanceLabel || t('outcome_' + (s.performance || 'theatre'));
            let html = '<div class="bc-debrief">';
            html += '<div class="bc-debrief-tag">' + t('debrief_tag') + '</div>';
            html += '<div class="bc-debrief-score"><span class="bc-debrief-num">' + score + '</span><span class="bc-debrief-den"> / 100</span></div>';
            html += '<div class="bc-debrief-band">' + label + '</div>';
            html += '<div class="bc-debrief-kpis">' + t('debrief_value') + ' ' + (s.totalValue || 0) +
                    ' &nbsp;·&nbsp; ' + t('debrief_prep') + ' ' + (s.preparation || 0) +
                    ' &nbsp;·&nbsp; ' + t('debrief_trust') + ' ' + (s.boardTrust || 0) + '</div>';
            html += '<ul class="bc-debrief-list">';
            const ins = s.insights || [];
            for (let i = 0; i < ins.length; i++) html += '<li>' + ins[i] + '</li>';
            html += '</ul>';
            html += '<p class="bc-debrief-close">' + t('debrief_close') + '</p>';
            html += '</div>';
            return html;
        }

